#include <bits/stdc++.h>
using namespace std;
int main(){
    long long v;
    while (cin >> v && v != 0) {
        vector<long long> results;
        for (int d=0; d<=9; d++) {
            long long rem = v - d;
            if (rem <= 0) continue;
            if (rem % 9 != 0) continue;
            long long M = rem / 9;
            if (M < 1) continue;
            long long N = 10*M + d;
            results.push_back(N);
        }
        sort(results.begin(), results.end());
        for (size_t i=0;i<results.size();i++) {
            if (i) cout << " ";
            cout << results[i];
        }
        cout << "\n";
    }
}

